const lead = $input.first().json;

if (!lead || typeof lead !== 'object') {
  return [{ json: { error: true, reason: 'invalid_payload', lead: null } }];
}
if (!lead.email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(lead.email))) {
  return [{ json: { error: true, reason: 'missing_or_invalid_email', lead, score: 0 } }];
}

return [{ json: { ...lead, emailValid: true } }];

const lead = $input.first().json;
if (lead.error) return [{ json: lead }];

const postgres = Postgres.main;
try {
  const existing = await postgres.query(`SELECT id, status, created_at FROM leads WHERE email = $1 LIMIT 1`, [lead.email]);
  if (existing.rows.length > 0) {
    return [{ json: { ...lead, isDuplicate: true, existingLeadId: existing.rows[0].id, existingStatus: existing.rows[0].status } }];
  }
} catch (e) {}

return [{ json: { ...lead, isDuplicate: false } }];

const lead = $input.first().json;
if (lead.error) return [{ json: lead }];

let companySize = 0;
let industry = lead.industry || 'unknown';
let companyDomain = '';

try {
  const domain = (lead.company_domain || lead.company || '').toLowerCase().replace(/[^a-z0-9.-]/g, '');
  if (domain && process.env.CLEARBIT_API_KEY) {
    const resp = await fetch(`https://company.clearbit.com/v2/companies/find?domain=${domain}`, {
      headers: { 'Authorization': `Bearer ${process.env.CLEARBIT_API_KEY}` },
      signal: AbortSignal.timeout(5000)
    });
    if (resp.ok) {
      const co = await resp.json();
      companySize = co.employees || 0;
      industry = co.industry || industry;
      companyDomain = co.domain || domain;
    }
  }
} catch (e) {}

return [{ json: { ...lead, companySize, industry, companyDomain, enrichedAt: new Date().toISOString() } }];

const lead = $input.first().json;
if (lead.error) return [{ json: lead }];

let score = 30;
if (lead.source === 'demo_request') score += 20;
else if (lead.source === 'referral') score += 25;
else if (lead.source === 'inbound') score += 15;
else if (lead.source === 'outbound') score += 5;

if (lead.companySize > 500) score += 25;
else if (lead.companySize > 100) score += 15;
else if (lead.companySize > 20) score += 5;

if (['government', 'finance', 'technology', 'healthcare'].includes((lead.industry || '').toLowerCase())) score += 10;
if (lead.company) score += 10;
if (lead.phone) score += 5;
if (lead.message && lead.message.length > 20) score += 5;

score = Math.min(score, 100);
let tier = 'low';
if (score >= 80) tier = 'high';
else if (score >= 50) tier = 'medium';

return [{ json: { ...lead, score, tier } }];
